import { spawn } from 'node:child_process';

const baseURL = process.env.PLAYWRIGHT_BASE_URL || 'http://localhost:4242';
const parsedBaseURL = new URL(baseURL);
const port = Number(parsedBaseURL.port || 4242);
const readinessURL = `${baseURL.replace(/\/$/, '')}/__playwright_e2e_ready`;

async function inspectExistingServer() {
    try {
        const response = await fetch(readinessURL, { signal: AbortSignal.timeout(1_000) });
        const contentType = response.headers.get('content-type') || '';
        const body = contentType.includes('application/json')
            ? await response.json().catch(() => null)
            : null;

        if (response.ok && body?.e2eReady === true) return 'ready';

        console.error(
            `[Playwright] A server is already responding at ${baseURL}, but it is not the E2E server ` +
            `(expected ${readinessURL} to report e2eReady=true). Stop that server or set PLAYWRIGHT_BASE_URL ` +
            `to an unused local port before running browser tests.`,
        );
        process.exit(1);
    } catch (error) {
        if (error instanceof TypeError || error?.cause?.code === 'ECONNREFUSED') return 'not-running';
        if (error?.name === 'TimeoutError') {
            console.error(`[Playwright] Could not verify the server at ${readinessURL}: ${error.message}`);
            process.exit(1);
        }
        throw error;
    }
}

if (await inspectExistingServer() === 'ready') {
    // Playwright normally reuses this server before launching webServer.command.
    // Keep this fallback process alive in case startup probing races with us.
    await new Promise((resolve) => {
        process.once('SIGINT', resolve);
        process.once('SIGTERM', resolve);
    });
} else {
    const child = spawn(
        'npx',
        ['--no-install', 'vite', '--config', 'packages/renderer/vite.config.ts', '--port', String(port), '--strictPort'],
        {
            stdio: 'inherit',
            env: {
                ...process.env,
                PORT: String(port),
                VITE_E2E: 'true',
                VITE_FIREBASE_E2E_MOCK: 'true',
                VITE_RENDERER_ONLY: 'true',
            },
        },
    );

    for (const signal of ['SIGINT', 'SIGTERM']) {
        process.once(signal, () => child.kill(signal));
    }

    child.once('error', (error) => {
        console.error(`[Playwright] Failed to start the E2E Vite server: ${error.message}`);
        process.exitCode = 1;
    });
    child.once('exit', (code, signal) => {
        process.exitCode = code ?? (signal ? 1 : 0);
    });
}

